protocol_fields := {"protocol", "scheme", "url", "endpoint", "address", "connection_string", "hostname", "connection_uri", "broker_url", "server_address", "listener_protocol", "frontend_protocol", "security_protocol", "endpoint_type", "source"}

# Check if any string in value contains unencrypted protocol
value_contains_unencrypted_protocol(value) {
    walk(value, [_, n])
    n.ir_type == "String"
    startswith(lower(n.value), unencrypted_protocols[_])
}

# Check if value indicates disabled security (boolean false or string "no"/"false")
is_security_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower(value.value) == "no"
} else {
    value.ir_type == "String"
    lower(value.value) == "false"
} else {
    value.ir_type == "String"
    lower(value.value) == "off"
} else {
    value.ir_type == "String"
    lower(value.value) == "disabled"
}

# Check if value indicates enabled insecure flag (boolean true or string "yes"/"true")
is_insecure_enabled(value) {
    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "String"
    lower(value.value) == "yes"
} else {
    value.ir_type == "String"
    lower(value.value) == "true"
} else {
    value.ir_type == "String"
    lower(value.value) == "on"
} else {
    value.ir_type == "String"
    lower(value.value) == "enabled"
}

# Check for weak TLS version
is_weak_tls_version(value) {
    value.ir_type == "String"
    ver := lower(value.value)
    contains(ver, weak_tls_versions[_])
}

# Check if attribute name matches any pattern
name_matches_patterns(name, patterns) {
    lower_name := lower(name)
    pattern := patterns[_]
    contains(lower_name, pattern)
}

# Check if attribute enables insecurity through disabled encryption
attribute_enables_insecurity(attr) {
    name_matches_patterns(attr.name, encryption_enforcement_fields)
