package glitch

import data.glitch_lib

# Protocol and security field patterns
protocol_fields := {"protocol", "scheme", "url", "endpoint", "address", "connection_string", "hostname", "connection_uri", "broker_url", "server_address", "source", "location"}

security_enforcement_fields := {"require_secure_transport", "enable_https_traffic_only", "enforce_https", "encryption_in_transit", "encrypt_traffic", "secure_transport", "ssl_enforcement_enabled", "require_ssl", "tls", "use_ssl", "start_tls", "enforce_https", "https_only"}

insecurity_flags := {"tls_disabled", "ssl_disabled", "insecure_skip_verify", "allow_unencrypted", "permit_http", "ignore_certificate_errors", "accept_insecure_connections", "validate_certs", "ssl_skip_verify", "verifypeer", "verify_ssl", "verify_peer"}

weak_tls_versions := {"1.0", "1.1", "sslv2", "sslv3", "tlsv1", "tlsv1.1", "sslv2", "sslv3"}

# Check if string value contains unencrypted protocol pattern
contains_unencrypted_protocol(value) {
    walk(value, [_, node])
    node.ir_type == "String"
    lower_str := lower(node.value)
    regex.match(`^(https?://|ftp://|telnet://|http$|ftp$|http:|ftp:)`, lower_str)
    not regex.match(`^https://`, lower_str)
}

# Check if value indicates disabled/bad security (false, "no", "false", "off", "disabled", 0)
is_security_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower(value.value) == "no"
} else {
    value.ir_type == "String"
    lower(value.value) == "false"
} else {
    value.ir_type == "String"
    lower(value.value) == "off"
} else {
    value.ir_type == "String"
    lower(value.value) == "disabled"
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Check if value indicates enabled insecure flag (true, "yes", "true", "on", "enabled", 1)
is_insecure_enabled(value) {
    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "String"
    lower(value.value) == "yes"
} else {
    value.ir_type == "String"
    lower(value.value) == "true"
} else {
    value.ir_type == "String"
    lower(value.value) == "on"
} else {
    value.ir_type == "String"
    lower(value.value) == "enabled"
} else {
    value.ir_type == "Integer"
    value.value == 1
}

# Check for weak TLS version
is_weak_tls_version(value) {
    value.ir_type == "String"
    ver := lower(value.value)
    contains(ver, weak_tls_versions[_])
}

# Generic name matcher
name_matches(name, patterns) {
    lower_name := lower(name)
    pattern := patterns[_]
    contains(lower_name, pattern)
}

# Check attribute for unencrypted protocol
attr_has_unencrypted_protocol(attr) {
    name_matches(attr.name, protocol_fields)
    contains_unencrypted_protocol(attr.value)
}

# Check attribute for disabled security enforcement
attr_has_disabled_security(attr) {
    name_matches(attr.name, security_enforcement_fields)
    is_security_disabled(attr.value)
}

# Check attribute for enabled insecurity flag
attr_has_enabled_insecurity(attr) {
    name_matches(attr.name, insecurity_flags)
    is_insecure_enabled(attr.value)
}

# Check attribute for weak TLS version
attr_has_weak_tls(attr) {
    name_matches(attr.name, {"tls_version", "ssl_version", "min_tls_version", "minimum_tls_version", "security_protocol"})
    is_weak_tls_version(attr.value)
}

# Recursively check Hash entries for security issues
check_hash_entries(value) {
    walk(value, [_, node])
    node.ir_type == "Hash"
    entry := node.value[_]
    entry.key.ir_type == "String"
    entry_key := lower(entry.key.value)

    # Check for protocol fields with unencrypted values
    pattern := protocol_fields[_]
    contains(entry_key, pattern)
    contains_unencrypted_protocol(entry.value)
} else {
    walk(value, [_, node])
    node.ir_type == "Hash"
    entry := node.value[_]
    entry.key.ir_type == "String"
    entry_key := lower(entry.key.value)

    # Check for security enforcement fields that are disabled
    pattern := security_enforcement_fields[_]
    contains(entry_key, pattern)
    is_security_disabled(entry.value)
} else {
    walk(value, [_, node])
    node.ir_type == "Hash"
    entry := node.value[_]
    entry.key.ir_type == "String"
    entry_key := lower(entry.key.value)

    # Check for insecurity flags that are enabled
    pattern := insecurity_flags[_]
    contains(entry_key, pattern)
    is_insecure_enabled(entry.value)
}

# Main rule: detect unencrypted protocols in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    unit := atomic_units[_]
    attrs := glitch_lib.all_attributes(unit)
    attr := attrs[_]
    attr_has_unencrypted_protocol(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Unencrypted protocols should not be used for transmitting sensitive data. (CWE-319)"
    }
}

