protocol_fields := {"protocol", "scheme"}

insecurity_flag_fields := {"validate_certs", "ssl_verify", "tls_verify", "verify_ssl", "verify_peer", "verifypeer", "insecure_skip_verify", "ssl_skip_verify", "tls_skip_verify", "ignore_certificate_errors", "accept_insecure_connections", "allow_unencrypted", "permit_http", "force", "strictssl", "strict_ssl", "check_ssl", "check_certificate"}

