disabled_patterns := {"false", "no", "off", "disabled", "0"}
enabled_patterns := {"true", "yes", "on", "enabled", "1"}

# Walk through any value type to find strings containing unencrypted protocols
find_unencrypted_protocol_in_value(value) {
    walk(value, [path, node])
    node.ir_type == "String"
    lower_val := lower(node.value)
    startswith(lower_val, unencrypted_patterns[_])
